colourBodies.metal:
float coverage=clamp(dot(m,channels),0.0,1.0);
if(invert>0.5) coverage=1.0-coverage;
return float4(c.rgb,c.a*coverage);

colourBodies.glsl:
float coverage=clamp(dot(m,channels),0.0,1.0);
if(invert>0.5) coverage=1.0-coverage;
return vec4(c.rgb,c.a*coverage);

